val displayExp = """(\\d+)""".r
val escapedChar = """\\(.)""".r

def fixMultiplication(x: Any, y: Any): Any = x * y

val numPoints = 10000
var sum = 0
for (i <- 0 until numPoints) {
  val firstNumber = displayExp.findFirstMatchIn(s"$i") match {
    case Some(m) =>
      val exponent = m.group(1).toInt
      fixMultiplication(2, Math.pow(10, exponent))
    case None =>
      2
  }
  val secondNumber = escapedChar.findFirstMatchIn(s"$i") match {
    case Some(m) =>
      val escapedChar = m.group(1).toChar
      if (escapedChar == 'e') {
        fixMultiplication(2, Math.pow(10, 1))
      } else {
        fixMultiplication(2, Math.pow(10, -2))
      }
    case None =>
      if (i == 0) {
        fixMultiplication(2, Math.pow(10, 1))
      } else {
        fixMultiplication(2, Math.pow(10, -2))
      }
  }
  val product = fixMultiplication(firstNumber, secondNumber)
  sum += product
}
println(sum)
```

