void FindDuplicates(int a[], int n) {
int duplicate = 0;
int i;
int j;

for (i=1; i<n; i++){
if (a[i] > 1) {
for (j=i-1; j>0; j--){
if (a[i] == a[j] && a[j] > 1){
duplicate = 1;
break;
}
}
}
}
}
