private static IEnumerable<int> PrimesLessThan(int n)
{
// Check if n is a non-negative integer.
if (n < 0) return Enumerable.Empty<int>();
// Create a new int for the output.
int k = 0;
// Now calculate the number of primes less than n.
for (int i = 2; i < n; ++i)
{
k += (n % i == 0) ? 0 : 1;
// When you find a number where n % i is 0 or 1 then...
}
return Enumerable.Range(2, k);
}

