def fib(n):
a, b = 0, 1
while n > 0:
a, b = b, a + b
yield b
n -= 1

def fibPrime(n):
a, b = 0, 1
while n > 0:
a, b = b, a + b
yield int(a)
n -= 1

def nPrimes(n):
for i in range(1, n+1):
if len(fib(n-i)) > 1:
yield i

def power(n):
if n == 0:
return 1
else:
product = power(n - 1)
if n % 2 == 0:
return product*product
else:
return product*product*n

def inverse(a):
if a == 0:
return 1
elif a == 1:
return -1
else:
return inverse(int(a-1)) + 1

