// Compute the power of 10 that is nearest to the specified number and returns
// the power of 10 and the count of 0's that are neccessary to get that number
int nearestPower(long long quantity) {
int power = 0; long long count = 0;

while (pow(10, power) < quantity) {
count++;
power += 1;
}

while (pow(10, power) > quantity) {
power -= 1;
}

return power;
}
int main() {

// prompt and test for argument
printf("PROMPT: Enter the number of book volumes in University of California Libraries: ");
long long count = 0; long long volume = 0;
long long quantity = 0; int power = 0;
while (scanf("%lld", &quantity) && quantity != 0) {
printf("Enter the answer to the problem: ");
long long answer = 0;
while (scanf("%lld", &answer) && answer != 0) {
volume = pow(10, power);
count = abs(quantity - volume);
printf("Ratio: %.3f\n", count / volume);

if (count < answer) {
power += 1;
} else {
power -= 1;
}

if (count == answer) {
power = nearestPower(count);
break;
}

}

report(quantity, volume, power);

printf("Starting over, please.");
printf("\n\n\n\n");
printf("Enter the number of book volumes in University of California Libraries: ");
}

return 0;
}


