class Solution {
public:
    double powerOfTenProbability(int A, int B) {
        double prob1 = 0.000, prob2 = 1.0, prob3 = 0.000;
        if (A == 0) {
            prob1 = prob2 = 1.0;
        } else {
            prob1 = 1.0 / 10.0;
        }
        for (int i = 1; i < A + 1; ++i) {
            if (i == 1) prob2 = prob2 * i;
            else prob2 = prob2 / 10.0 * i;
            prob3 = prob2 * prob1;
        }
        prob3 = prob3 * prob1;
        return prob3;
    }
    double nearestPowersOfTen(int N) {
        int lower = log10(N) / log10(2);
        int upper = log10(N) / log10(2) + 1;
        int mid = (lower + upper) / 2;
        double prob2 = 1.0;
        double prob3 = 0.0;
        int x;
        for (x = log10(N) / log10(2); x >= 0; x -= 1) {
            prob2 = prob2 * pow(10.0, x);
        }
        for (x = log10(N) / log10(2); x < 0; x += 1) {
            prob3 = prob3 + 0.5;
        }
        return powerOfTenProbability(lower, mid) + powerOfTenProbability(mid, upper) - (pow(2, 10) / (pow(2, 10) + 1)) * prob2 - prob3 / 10.0;
    }
};

