    mult = 1;
    exp = 0;
    while (input > 1)
    {
        input /= 10;
        exp++;
    }
    return pow(10, exp);
}

int inversePower10(int power)
{
    return 1.0 / power;
}

int main()
{
    int input;
    double laser;
    input = 15718754500;
    laser = power10(input) + 1.91 * inversePower10(power10(input)) / 1000;
    printf("The additional acceleration of Voyager 1 by shining a red laser pointer at it, in meters per second squared is: %.10lf\n", laser);
    return 0;
}
```

